arguments.command:
curl -s "https://api.box.com/2.0/folders/8100/items?limit=1000&fields=id,name,type,owned_by,created_by" | python3 -c "
import json,sys
d=json.load(sys.stdin)
for e in d['entries']:
    if e['type']=='folder':
        o=e.get('owned_by') or {}
        c=e.get('created_by') or {}
        print(e['id'], repr(e['name']), '| owner:', o.get('name'), o.get('login'), '| created_by:', c.get('name'), c.get('login'))
"

